import { Table, ReferenceColumn, StringColumn, GuidColumn } from '@servicenow/sdk/core'

export const sys_hub_flow_logic_instance_v2 = Table({
    allowWebServiceAccess: true,
    attributes: {
        domain_master: 'flow',
        update_synch: false,
    },
    extends: 'sys_hub_flow_component',
    label: 'Flow Logic Instance V2',
    name: 'sys_hub_flow_logic_instance_v2',
    schema: {
        block: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Block',
            referenceTable: 'sys_hub_flow_block',
        }),
        workflow_reference: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Workflow reference',
            referenceTable: 'wf_workflow',
        }),
        connected_to: StringColumn({
            label: 'Connected To',
            maxLength: 255,
        }),
        logic_definition: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Logic definition',
            referenceTable: 'sys_hub_flow_logic_definition',
        }),
        values: StringColumn({
            label: 'Values',
            maxLength: 16777215,
        }),
        outputs_assigned: StringColumn({
            label: 'Outputs assigned',
            maxLength: 4000,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        flow_variables_assigned: StringColumn({
            label: 'Flow variables assigned',
            maxLength: 4000,
        }),
        decision_table: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Decision table',
            referenceTable: 'sys_decision',
        }),
    },
})
